#include <bits/stdc++.h>using namespace std; int main() {    ios::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;     while (t--) {        int n, k;        cin >> n >> k;         vector<string> strips(k);        for (int i = 0; i < k; i++) {            cin >> strips[i];        }         // allowed[i] = bitmask of possible characters at position i        vector<int> allowed(n, 0);         for (int i = 0; i < n; i++) {            int mask = 0;            for (int j = 0; j < k; j++) {                mask |= (1 << (strips[j][i] - 'a'));            }            allowed[i] = mask;        }         // find all divisors of n        vector<int> divisors;        for (int d = 1; d * d <= n; d++) {            if (n % d == 0) {                divisors.push_back(d);                if (d != n / d)                    divisors.push_back(n / d);            }        }        sort(divisors.begin(), divisors.end());         string answer;        bool found = false;         // try smallest d first        for (int d : divisors) {            vector<int> chosen(d, 0);            bool ok = true;             for (int r = 0; r < d; r++) {                int common = (1 << 26) - 1;  // all letters possible                 for (int pos = r; pos < n; pos += d) {                    common &= allowed[pos];                }                 if (common == 0) {                    ok = false;                    break;                }                 chosen[r] = common;            }             if (ok) {                // construct the answer                answer.resize(n);                for (int i = 0; i < d; i++) {                    int c = __builtin_ctz(chosen[i]); // pick any valid char                    for (int pos = i; pos < n; pos += d) {                        answer[pos] = char('a' + c);                    }                }                found = true;                break;            }        }         cout << answer << "\n";    }     return 0;}